from collections import deque, defaultdict

def transform(grid):
    R, C = len(grid), len(grid[0])
    cnt = {}
    for r in grid:
        for v in r:
            cnt[v] = cnt.get(v, 0) + 1
    bg = max(cnt, key=cnt.get)
    seen = [[False]*C for _ in range(R)]
    objs = []
    for i in range(R):
        for j in range(C):
            if grid[i][j] != bg and not seen[i][j]:
                col = grid[i][j]
                q = deque([(i, j)]); seen[i][j] = True
                cells = []
                while q:
                    r, c = q.popleft(); cells.append((r, c))
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < R and 0 <= nc < C and not seen[nr][nc] and grid[nr][nc] == col:
                            seen[nr][nc] = True; q.append((nr, nc))
                rs = [r for r, _ in cells]; cs = [c for _, c in cells]
                mr, mc = min(rs), min(cs)
                shape = frozenset((r-mr, c-mc) for r, c in cells)
                objs.append({'col': col, 'cells': cells, 'mr': mr, 'mc': mc,
                             'shape': shape, 'h': max(rs)-mr+1, 'w': max(cs)-mc+1, 'n': len(cells)})
    bycolor = defaultdict(list)
    for o in objs:
        bycolor[o['col']].append(o)
    cand = []
    for col, os_ in bycolor.items():
        if col == bg:
            continue
        if len(os_) <= 2:
            md = max(max(o['h'], o['w']) for o in os_)
            cand.append((md, col))
    line_col = max(cand)[1] if cand else None
    best = None
    for a in objs:
        if a['mr'] != 0:
            continue
        for b in objs:
            if b['col'] == a['col'] or b['shape'] != a['shape']:
                continue
            if (b['mr'], b['mc']) < (a['mr'], a['mc']):
                earlier, later = b, a
            else:
                earlier, later = a, b
            if earlier['mr'] != 0:
                continue
            key = (later['n'], -(later['mr']*1000 + later['mc']))
            if best is None or key > best[0]:
                best = (key, later)
    out = [row[:] for row in grid]
    if best is not None and line_col is not None:
        for r, c in best[1]['cells']:
            out[r][c] = line_col
    else:
        pool = [(len(os_), col) for col, os_ in bycolor.items() if col not in (bg, line_col)]
        if pool and line_col is not None:
            pool.sort()
            col = pool[0][1]
            tgt = max(bycolor[col], key=lambda o: (o['n'], -(o['mr']*1000 + o['mc'])))
            for r, c in tgt['cells']:
                out[r][c] = line_col
    return out
