from collections import deque, Counter, defaultdict

def transform(grid):
    R, C = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]

    seen = [[False] * C for _ in range(R)]
    objs = []
    for i in range(R):
        for j in range(C):
            if grid[i][j] != bg and not seen[i][j]:
                col = grid[i][j]
                q = deque([(i, j)])
                seen[i][j] = True
                cells = []
                while q:
                    r, c = q.popleft()
                    cells.append((r, c))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C and not seen[nr][nc] and grid[nr][nc] == col:
                                seen[nr][nc] = True
                                q.append((nr, nc))
                objs.append({'col': col, 'cells': cells})

    bycol = defaultdict(list)
    for o in objs:
        bycol[o['col']].append(o)

    def maxrun(col):
        best = 0
        for r in range(R):
            run = 0
            for c in range(C):
                run = run + 1 if grid[r][c] == col else 0
                best = max(best, run)
        for c in range(C):
            run = 0
            for r in range(R):
                run = run + 1 if grid[r][c] == col else 0
                best = max(best, run)
        return best

    nonbg = [c for c in bycol if c != bg]
    if not nonbg:
        return [row[:] for row in grid]
    line_col = min(nonbg, key=lambda c: (len(bycol[c]), -maxrun(c)))

    def norm(o):
        mr = min(r for r, c in o['cells'])
        mc = min(c for r, c in o['cells'])
        return frozenset((r - mr, c - mc) for r, c in o['cells'])

    for o in objs:
        o['shape'] = norm(o)

    top = [o for o in objs
           if o['col'] not in (bg, line_col) and any(r == 0 for r, c in o['cells'])]
    topset = set(id(o) for o in top)

    diff_cands = []
    for t in top:
        twins = [o for o in objs
                 if id(o) not in topset and o['shape'] == t['shape'] and o['col'] != line_col]
        for tw in twins:
            if tw['col'] != t['col']:
                diff_cands.append(tw)

    if diff_cands:
        tgt = max(diff_cands, key=lambda o: (len(o['cells']), -min(r for r, c in o['cells'])))
    elif top:
        tgt = max(top, key=lambda o: len(o['cells']))
    else:
        groups = defaultdict(list)
        for o in objs:
            groups[o['shape']].append(o)
        pairs = [g for g in groups.values() if len(g) > 1]
        if not pairs:
            return [row[:] for row in grid]
        p = max(pairs, key=lambda g: max(len(o['cells']) for o in g))
        tgt = max(p, key=lambda o: min(r for r, c in o['cells']))

    out = [row[:] for row in grid]
    for r, c in tgt['cells']:
        out[r][c] = line_col
    return out
